{"command":"node --env-file=apps/api/.env --input-type=module <<'NODE'
import { createRequire } from 'node:module';
import { spawnSync } from 'node:child_process';
const require = createRequire(new URL('./apps/api/package.json', `file://${process.cwd()}/`));
const postgres = require('postgres');
if (!process.env.DATABASE_URL) throw new Error('DATABASE_URL is required');
const databaseName = `seapilot_t03_t04_${process.pid}`;
const admin = postgres(process.env.DATABASE_URL, { max: 1 });
try {
  await admin.unsafe(`CREATE DATABASE ${databaseName}`);
  const testUrl = new URL(process.env.DATABASE_URL);
  testUrl.pathname = `/${databaseName}`;
  const env = { ...process.env, DATABASE_URL: testUrl.href, OPENAI_API_KEY: [REDACTED] };
  const migration = spawnSync('pnpm', ['--filter', '@seapilot/api', 'db:migrate'], { env, stdio: 'inherit' });
  if (migration.status !== 0) process.exitCode = migration.status ?? 1;
  else process.exitCode = spawnSync('pnpm', ['test'], { env, stdio: 'inherit' }).status ?? 1;
} finally {
  await admin.unsafe(`DROP DATABASE IF EXISTS ${databaseName} WITH (FORCE)`);
  await admin.end();
}
NODE"}
